// 124 Directory Accounts for Universal Smart Search & Verification
export const ADDITIONAL_DIRECTORY_ACCOUNTS: RegisteredAccountInfo[] = ALL_NEW_REGISTERED_ENTRIES.map(e => ({
  accountNumber: e.accountNumber,
  accountName: e.name,
  bankName: e.bankName,
  userId: e.id,
  phone: e.phone,
  isVerified: true,
  accountType: 'Savings Account'
}));

// UserProfiles for LocalDb
export const ADDITIONAL_USERS_SEED: UserProfile[] = ALL_NEW_REGISTERED_ENTRIES.map(e => ({
  id: e.id,
  name: e.name,
  phone: e.phone,
  email: e.email,
  role: 'user',
  status: 'active',
  createdAt: '2026-02-15T10:00:00Z',
  accountNumber: e.accountNumber,
  balance: e.balance,
  availableBalance: e.availableBalance,
  biometricEnabled: true
}));

// BankAccounts (one per unique account number with primary user as owner)
const uniqueAccMap = new Map<string, NewRegisteredAccountEntry>();
ALL_NEW_REGISTERED_ENTRIES.forEach(e => {
  if (!uniqueAccMap.has(e.accountNumber)) {
    uniqueAccMap.set(e.accountNumber, e);
  }
});

export const ADDITIONAL_BANK_ACCOUNTS: BankAccount[] = Array.from(uniqueAccMap.values()).map(e => ({
  id: 'acc_' + e.id,
  userId: e.id,
  accountName: e.name + ' Savings Account',
  accountNumber: e.accountNumber,
  accountType: 'savings',
  balance: e.balance,
  availableBalance: e.availableBalance,
  status: 'active',
  currency: 'ETB',
  isPrimary: true,
  createdAt: '2026-02-15T10:00:00Z'
}));
